var AU={
  "ce-matin": "data:audio/mpeg;base64,",
  "cet-apres-midi": "data:audio/mpeg;base64,",
  "cette-semaine": "data:audio/mpeg;base64,"
};
(function(){
var MAIL='florian-haas@mail.grokbot.com';
var $=function(s){return document.querySelector(s)};
function ls(k,v){try{if(v===undefined)return localStorage.getItem(k);localStorage.setItem(k,v)}catch(e){return null}}
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function iso(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
var TODAY=iso(new Date());
function theme(t){document.documentElement.dataset.theme=t;ls('fr-theme',t);$('#th').textContent=t==='dark'?'☀️':'🌙'}
theme(ls('fr-theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'));
$('#th').onclick=function(){theme(document.documentElement.dataset.theme==='dark'?'light':'dark')};
ls('fr-last',JSON.stringify({id:'wiederholung',href:'wiederholung.html',title:'Wiederholung',t:Date.now()}));

/* same reorder helper as in the lesson pipeline */
function RZ(z,arr,redraw,off){if(!document.getElementById("rzcss")){const c=document.createElement("style");c.id="rzcss";c.textContent=".rzs{outline:3px solid #4f6bff;outline-offset:1px}.rzb{box-shadow:-5px 0 0 #4f6bff}.rze{box-shadow:5px 0 0 #4f6bff}.rzg{position:fixed;z-index:99;pointer-events:none;opacity:.9;transform:scale(1.08);margin:0}.rzh{font-size:.8rem;opacity:.65;margin:2px 0 0}";document.head.appendChild(c);}
 if(!z.nextElementSibling||!z.nextElementSibling.classList.contains("rzh")){const h=document.createElement("div");h.className="rzh";h.textContent="Tippen = auswählen · nochmal tippen = zurück · ziehen oder antippen = verschieben";z.after(h);}
 const cs=[...z.querySelectorAll("button")],no=()=>off&&off();if(z._sel!=null&&z._sel<cs.length)cs[z._sel].classList.add("rzs");else z._sel=null;
 const mv=(f,t)=>{const it=arr.splice(f,1)[0];arr.splice(t,0,it);z._sel=null;redraw();},rm=n=>{arr.splice(n,1);z._sel=null;redraw();};
 z.onclick=e=>{if(no()||e.target!==z||z._sel==null)return;mv(z._sel,arr.length-1);};
 cs.forEach((b,n)=>{b.onclick=null;b.style.touchAction="none";
  b.onpointerdown=ev=>{if(no()||ev.button>0)return;ev.preventDefault();const sx=ev.clientX,sy=ev.clientY;let g=null,ti=-1;try{b.setPointerCapture(ev.pointerId);}catch(_){}
   const clr=()=>cs.forEach(c=>c.classList.remove("rzb","rze")),end=()=>{b.onpointermove=b.onpointerup=b.onpointercancel=null;if(g){g.remove();b.style.opacity="";}clr();};
   const idx=(x,y)=>{let k=0;cs.forEach((c,m)=>{if(m===n)return;const r=c.getBoundingClientRect(),cy=r.top+r.height/2;if(cy<y-r.height/2||(Math.abs(cy-y)<=r.height/2&&r.left+r.width/2<x))k++;});return k;};
   const inZ=(x,y)=>{const r=z.getBoundingClientRect();return x>=r.left-10&&x<=r.right+10&&y>=r.top-14&&y<=r.bottom+14;};
   b.onpointermove=e=>{if(!g&&Math.hypot(e.clientX-sx,e.clientY-sy)>8){const r=b.getBoundingClientRect();g=b.cloneNode(true);g.classList.add("rzg");g.classList.remove("rzs");g.style.width=r.width+"px";g._w=r.width/2;g._h=r.height/2;document.body.appendChild(g);b.style.opacity=".3";}
    if(!g)return;g.style.left=(e.clientX-g._w)+"px";g.style.top=(e.clientY-g._h)+"px";clr();if(inZ(e.clientX,e.clientY)){ti=idx(e.clientX,e.clientY);const o=cs.filter((c,m)=>m!==n);if(o[ti])o[ti].classList.add("rzb");else if(o.length)o[o.length-1].classList.add("rze");}};
   b.onpointerup=e=>{const d=!!g;end();if(d){if(inZ(e.clientX,e.clientY))mv(n,idx(e.clientX,e.clientY));else rm(n);return;}
    if(z._sel==null){z._sel=n;b.classList.add("rzs");}else if(z._sel===n)rm(n);else mv(z._sel,n);};
   b.onpointercancel=end;};});}

var cur=null;
function play(k,b,rate){try{if(!AU[k])return;if(cur)cur.pause();document.querySelectorAll(".play.on,.slowbtn.on").forEach(function(e){e.classList.remove("on")});cur=new Audio(AU[k]);if(rate)cur.playbackRate=rate;if(b){b.classList.add("on");cur.onended=function(){b.classList.remove("on")}}
cur.play().catch(function(e){if(b)b.classList.remove("on");console.info("Audio blockiert:",e.name)});}catch(e){console.info(e.name)}}
function wireplay(){document.querySelectorAll("#view .play, #view .slowbtn").forEach(function(b){b.onclick=function(){play(b.dataset.a,b,b.dataset.rate?+b.dataset.rate:undefined)}})}
var strip=function(s){return s.normalize("NFD").replace(/[\u0300-\u036f]/g,"")};
var norm=function(s){return s.toLowerCase().replace(/[’`´]/g,"'").replace(/[.,;:!?…«»"]/g," ").replace(/\s+/g," ").trim()};
function shuf(a){a=a.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),x=a[i];a[i]=a[j];a[j]=x}return a}

var DATA=null,LIST=[],S=null,X={};
var SK='fr-wdh-'+TODAY;

function dueItems(W){return (W.items||[]).filter(function(it){return it.status!=='sicher' && it.due<=TODAY})}
function buildList(W){
  var due=dueItems(W), hdWanted=['ce-matin','cet','cette-semaine'], used={}, list=[];
  hdWanted.forEach(function(id){
    var it=due.filter(function(x){return x.id===id && x.audio && AU[x.audio]})[0];
    if(it){list.push({f:it,t:'hdiktat'});used[it.id]=1}
  });
  var rest=due.filter(function(it){return !used[it.id]});
  rest.forEach(function(it,i){list.push({f:it,t:i%2===0?'mc':'tiles'})});
  return list;
}

function fresh(){return {date:TODAY,i:0,xp:0,log:[],done:false}}
function save(){ls(SK,JSON.stringify(S))}
function loadS(){try{var o=JSON.parse(ls(SK)||'null');if(o&&o.date===TODAY)return o}catch(e){}return fresh()}

function act(txt,fn,dis){var b=$('#act');b.textContent=txt;b.onclick=fn;b.disabled=!!dis;b.style.display='block'}
function hud(){var n=LIST.length||1;$('#fill').style.width=((S.done?1:S.i/n)*100)+'%';var due=dueItems(DATA).length;$('#sub').textContent=S.done?'Fertig für heute':'Heute fällig: '+due+' · '+S.xp+' XP'}

function whyBox(f,ok){return (ok?'':'Richtig: ')+'<b>'+esc(f.fr)+'</b><span class="rs">('+esc(f.rs)+')</span><span class="de">'+esc(f.de)+'</span><br><span class="mut">📘 Warum stimmt das? '+esc(f.rule)+'</span>'}
function fb(lvl,html){document.querySelectorAll('#view .fb.hint').forEach(function(e){e.remove()});var d=document.createElement('div');d.className='fb '+lvl;
  d.innerHTML=(lvl==='ok'?'✅ <b>Richtig!</b> ':lvl==='ok2'?'✅ <b>Im 2. Versuch richtig!</b> (halbe XP) ':lvl==='hint'?'💡 <b>Fast – noch ein Versuch.</b> Tipp: ':'❌ <b>Leider falsch.</b> ')+html;
  $('#view').appendChild(d);d.scrollIntoView({block:'nearest'})}

function start(){
  LIST=buildList(DATA);S=loadS();
  if(!LIST.length){empty();return}
  if(S.done){end();return}
  if(S.i>=LIST.length){end();return}
  show();
}

function empty(){
  var later=(DATA.items||[]).filter(function(it){return it.status!=='sicher' && it.due>TODAY}).sort(function(a,b){return a.due<b.due?-1:1});
  var sure=(DATA.items||[]).filter(function(it){return it.status==='sicher'}).length;
  $('#skip').style.display='none';$('#actbar').style.display='none';
  $('#sub').textContent='Heute ist nichts fällig';
  $('#view').innerHTML='<h2>Nichts fällig</h2><p>Heute stehen keine Wiederholungen an. Sätze, die du sicher kannst, kommen erst wieder, wenn ein neuer Fehler dazu kommt.</p>'+(later.length?'<p class="mut">Als Nächstes fällig: '+esc(later[0].due)+' · '+later.length+' Satz/Sätze.</p>':'')+(sure?'<p class="mut">'+sure+' Satz/Sätze sind schon als sicher markiert.</p>':'');
}

function show(){
  X={};hud();var e=LIST[S.i],f=e.f,v=$('#view');
  $('#skip').style.display='';
  if(e.t==='hdiktat'){tilesView(f,true);return}
  if(e.t==='tiles'){tilesView(f,false);return}
  mcView(f);
}

function mcView(f){
  X.opts=shuf([f.right].concat(f.wrong||[]));
  $('#view').innerHTML='<span class="tag">'+esc(f.type)+' · Lücke</span><h2>✏️ Welche Form passt?</h2><p><b style="font-size:1.15rem">'+esc(f.q)+'</b><br><span class="mut">'+esc(f.de)+'</span></p>'+
    X.opts.map(function(o,j){return '<button class="opt" data-j="'+j+'">'+(j+1)+') '+esc(o)+'</button>'}).join('');
  X.pick=function(j){if(X.done||$('#view .opt[data-j="'+j+'"]').disabled)return;X.sel=j;document.querySelectorAll('#view .opt:not(.wrong)').forEach(function(b){b.classList.toggle('sel',+b.dataset.j===j)});$('#act').disabled=false};
  document.querySelectorAll('#view .opt').forEach(function(b){b.onclick=function(){X.pick(+b.dataset.j)}});
  var chk=function(){var ok=X.opts[X.sel]===f.right;
    if(!ok&&!X.tr){X.tr=1;X.first=X.opts[X.sel];var b=$('#view .opt[data-j="'+X.sel+'"]');b.classList.remove('sel');b.classList.add('wrong');b.disabled=true;X.sel=null;fb('hint',esc((f.rule.split(/[.→]/)[0]||f.rule).trim()));act('Nochmal prüfen',chk,1);return}
    X.done=1;X.got=(X.first?X.first+' → ':'')+X.opts[X.sel];
    document.querySelectorAll('#view .opt').forEach(function(b){var o=X.opts[+b.dataset.j];if(o===f.right)b.classList.add('right');else if(+b.dataset.j===X.sel)b.classList.add('wrong')});
    finish(ok?(X.tr?'ok2':'ok'):'no',f.right);
  };
  act('Prüfen',chk,1);
}

function tilesView(f,hide){
  var words=f.fr.split(' '), extras=f.x||f.wrong||[], pool=words.concat(extras).map(function(w,k){return {w:w,k:k}});
  pool=shuf(pool);X.ans=[];X.all=words.concat(extras);X.want=words.join(' ');
  var title=hide?'<h2>🎧 Hördiktat</h2><p class="mut">Hör den Satz und bau ihn aus den Bausteinen. Der Text bleibt verborgen, bis du prüfst.</p>':
    '<h2>🧩 Bau den Satz</h2><p class="mut">'+esc(f.de)+'</p>';
  var audio=hide&&f.audio&&AU[f.audio]?'<div class="playrow"><button class="play big" data-a="'+f.audio+'" aria-label="Anhören">🔊</button><button type="button" class="slowbtn" data-a="'+f.audio+'" data-rate="0.7" aria-label="Langsamer anhören">🐢 Langsamer</button></div>':'';
  $('#view').innerHTML='<span class="tag">'+esc(f.type)+(hide?' · Hördiktat':' · Bausteine')+'</span>'+title+audio+
    '<div class="chips ansz" id="az"></div><div class="chips" id="bank">'+pool.map(function(p){return '<button class="chip" data-k="'+p.k+'">'+esc(p.w)+'</button>'}).join('')+'</div>';
  if(hide)wireplay();
  var draw=function(){$('#az').innerHTML=X.ans.map(function(k){return '<button class="chip" data-k="'+k+'">'+esc(X.all[k])+'</button>'}).join('');
    document.querySelectorAll('#bank .chip').forEach(function(b){b.classList.toggle('used',X.ans.indexOf(+b.dataset.k)>=0)});
    RZ($('#az'),X.ans,draw,function(){return X.done});$('#act').disabled=!X.ans.length};
  document.querySelectorAll('#bank .chip').forEach(function(b){b.onclick=function(){if(X.done||b.classList.contains('used'))return;X.ans.push(+b.dataset.k);draw()}});
  var chk=function(){var said=X.ans.map(function(k){return X.all[k]}).join(' '),ok=norm(said)===norm(X.want);
    if(!ok&&!X.tr){X.tr=1;X.first=said;fb('hint',esc((f.rule.split(/[.→]/)[0]||f.rule).trim())+' – verschieb oder tausch die Bausteine.');act('Nochmal prüfen',chk);return}
    X.done=1;X.got=(X.first?X.first+' → ':'')+said;if(hide)play(f.audio);finish(ok?(X.tr?'ok2':'ok'):'no',X.want);
  };
  act('Prüfen',chk,1);
  if(hide){var big=document.querySelector('#view .play.big');if(big)setTimeout(function(){play(f.audio,big)},250)}
}

function finish(lvl,sol){
  var f=LIST[S.i].f, ok=lvl!=='no';
  if(ok)S.xp+=lvl==='ok'?10:5;
  fb(lvl,whyBox(f,ok));
  S.log.push({id:f.id,type:f.type,t:LIST[S.i].t,s:lvl==='ok'?'OK':lvl==='ok2'?'OK-2.VERSUCH':'FALSCH',soll:sol,ich:X.got||'',fr:f.fr,rs:f.rs,de:f.de,rule:f.rule});
  save();
  $('#skip').style.display='none';
  act('Weiter',next);
}

$('#skip').onclick=function(){
  if(!LIST[S.i]||X.done)return;
  var f=LIST[S.i].f,sol=LIST[S.i].t==='mc'?f.right:f.fr;
  S.log.push({id:f.id,type:f.type,t:LIST[S.i].t,s:'ÜBERSPRUNGEN',soll:sol,ich:'',fr:f.fr,rs:f.rs,de:f.de,rule:f.rule});
  save();next();
};

function next(){S.i++;save();if(S.i>=LIST.length)end();else show()}

function report(){
  var lid='WDH-'+TODAY, ok=0,o2=0,FK={},out=[];
  S.log.forEach(function(L,n){
    if(L.s==='OK')ok++;if(L.s==='OK-2.VERSUCH')o2++;
    if(L.s!=='OK')FK[L.type]=(FK[L.type]||0)+1;
    var tn=L.t==='mc'?'Lücke':L.t==='hdiktat'?'Hördiktat':'Bausteine';
    out.push(lid+'-'+String(n+1).padStart(2,'0')+' '+tn+' ['+L.type+'] '+L.id+' '+L.s+(L.s!=='OK'&&L.s!=='ÜBERSPRUNGEN'?' | soll: '+L.soll+' | ich: '+L.ich:L.s==='ÜBERSPRUNGEN'?' | soll: '+L.soll:''));
  });
  return 'FR-ERGEBNIS '+lid+' '+TODAY+' Wiederholung\nXP '+S.xp+' | '+ok+'/'+S.log.length+' OK, '+o2+' im 2. Versuch\nFehlerarten: '+(Object.keys(FK).map(function(k){return k+' '+FK[k]}).join(', ')||'keine')+'\n'+out.join('\n');
}

function end(){
  S.done=true;save();hud();$('#skip').style.display='none';
  var ok=S.log.filter(function(l){return l.s==='OK'}).length;
  var bad=S.log.filter(function(l){return l.s!=='OK'});
  var txt=report();
  var review=bad.length?'<div class="rvc"><h3>🔎 Fehler-Rückblick ('+bad.length+')</h3>'+bad.map(function(l){return '<div class="mist'+(l.s==='OK-2.VERSUCH'?' two':'')+'"><span class="tag">'+esc(l.type)+'</span> '+(l.s==='OK-2.VERSUCH'?'🟡 2. Versuch':l.s==='ÜBERSPRUNGEN'?'⏭️ übersprungen':'❌ falsch')+'<br><span class="mut">Du: '+esc(l.ich||'–')+'</span><br>✔ <b>'+esc(l.fr)+'</b><span class="rs">('+esc(l.rs)+')</span><span class="de">'+esc(l.de)+'</span><span class="mut">📘 Warum stimmt das? '+esc(l.rule)+'</span></div>'}).join('')+'</div>':
    '<div class="rvc"><h3>🔎 Fehler-Rückblick</h3><p>Alles im ersten Versuch richtig. Stark! 💪</p></div>';
  $('#view').innerHTML='<div class="bigx">'+(bad.length?'💪':'🏆')+'</div><h2 style="text-align:center">Wiederholung geschafft!</h2><div class="stats"><div><b>'+ok+'/'+S.log.length+'</b>richtig</div><div><b>'+S.xp+'</b>XP</div><div><b>'+bad.length+'</b>offen</div></div>'+review+
    '<button class="opt" id="cp" style="text-align:center;font-weight:700;background:var(--pri);color:#fff">📋 Ergebnis kopieren</button>'+
    '<button class="opt" id="qsend" style="text-align:center;font-weight:700;background:#22a45d;color:#fff">✉️ Ergebnis senden</button>'+
    '<div id="cpm" class="mut"></div><textarea id="ta" readonly rows="8" style="display:none"></textarea>'+
    '<p class="mut">Schick das Ergebnis, dann trage ich die Abstände 1 · 3 · 7 Tage in deiner Liste nach. Ohne Senden bleibt der Stand auf der Seite unverändert.</p>'+
    '<button class="ghost" id="again" style="display:block;margin:1rem auto 0">Noch einmal üben</button>';
  $('#ta').value=txt;window.__copied=txt;
  $('#cp').onclick=function(){var done=false;var go=function(m){$('#cpm').textContent=m};
    (navigator.clipboard?navigator.clipboard.writeText(txt):Promise.reject()).then(function(){go('✅ Kopiert! Jetzt im Chat einfügen.')},function(){var ta=$('#ta');ta.style.display='block';ta.focus();ta.select();try{done=document.execCommand('copy')}catch(e){}go(done?'✅ Kopiert! Jetzt im Chat einfügen.':'Bitte den Text unten markieren und kopieren.')})};
  $('#qsend').onclick=function(){location.href='mailto:'+MAIL+'?subject='+encodeURIComponent('FR-ERGEBNIS WDH-'+TODAY)+'&body='+encodeURIComponent(txt)};
  $('#again').onclick=function(){S=fresh();save();start()};
  act('Zurück zum Menü',function(){location.href='index.html'});
}

fetch('data/wiederholung.json?v='+Date.now()).then(function(r){if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}).then(function(W){DATA=W;start()}).catch(function(e){
  $('#skip').style.display='none';$('#act').style.display='none';
  $('#view').innerHTML='<p>Die Wiederholungsliste konnte nicht geladen werden.</p><p class="mut">'+esc(e.message||e)+'</p>';
});
})();
